import json, sys, io
sys.stdout = io.TextIOWrapper(sys.stdout.buffer, encoding='utf-8')
p = r'C:\Users\wyj\.codex\sessions\2026\09\05\rollout-2026-09-05T16-20-11-01a070a7-5ce3-7601-a316-081c130d4ad9.jsonl'
# print all user/assistant texts plus item types at end
for i, line in enumerate(open(p, encoding='utf-8', errors='replace')):
    try:
        d = json.loads(line)
    except Exception:
        continue
    pl = d.get('payload', {})
    t = pl.get('type', '')
    if t == 'message':
        role = pl.get('role', '')
        if role not in ('user', 'assistant'):
            continue
        parts = []
        for c in pl.get('content', []):
            if isinstance(c, dict):
                if c.get('type') in ('input_text', 'output_text', 'text'):
                    parts.append(c.get('text', ''))
                elif c.get('type') == 'tool_use':
                    name = c.get('name', '')
                    inp = json.dumps(c.get('input', {}), ensure_ascii=False)
                    parts.append(f"[TOOL_USE {name}] {inp[:400]}")
                elif c.get('type') == 'tool_result':
                    res = c.get('content')
                    if isinstance(res, list):
                        res = ' '.join(x.get('text', '') if isinstance(x, dict) else str(x) for x in res)
                    parts.append(f"[TOOL_RESULT] {str(res)[:400]}")
        if parts:
            print(f"== {role} @{d.get('timestamp','')} ==")
            for pr in parts:
                print(pr[:1200])
            print()
    elif t == 'response_item':
        sub = pl.get('payload', {})
        st = sub.get('type', '')
        if st == 'message' and sub.get('role') in ('user', 'assistant'):
            role = sub.get('role')
            parts = []
            for c in sub.get('content', []):
                if isinstance(c, dict):
                    if c.get('type') in ('input_text', 'output_text'):
                        parts.append(c.get('text', ''))
            if parts:
                print(f"== {role}(resp_item) @{d.get('timestamp','')} ==")
                for pr in parts:
                    print(pr[:1200])
                print()
    elif t == 'event_msg':
        sub = pl.get('payload', {})
        m = sub.get('message', '')
        if m:
            ms = str(m)
            if any(k in ms.lower() for k in ('sandbox', 'error', 'fail', '设置', '沙盒', 'elevat', 'admin', 'finish')):
                print(f"** EVENT @{d.get('timestamp','')}: {ms[:600]}")
